const guideCSS = `.guide-map{padding:22px;border:1px solid #29384a;border-radius:14px;background:#090d12;overflow:auto}.guide-flow{position:relative;display:grid;grid-template-columns:250px 90px 250px 90px 250px 90px 250px 90px 250px;column-gap:0;align-items:center;min-width:1610px;min-height:340px}.guide-column{position:relative;z-index:2;display:grid;gap:9px;align-content:center}.guide-heading{margin-bottom:5px;color:var(--muted);font-size:11px;font-weight:800;letter-spacing:.09em;text-transform:uppercase}.guide-node{display:flex;align-items:center;gap:9px;min-height:38px;padding:8px 10px;border:1px solid transparent;border-radius:8px;color:#dce5f1;cursor:pointer}.guide-node:hover{background:#121a24}.guide-node:has(input:checked){border-color:#66a7ff;background:#10213a;color:#fff}.guide-node input{appearance:none;width:14px;height:14px;flex:0 0 auto;margin:0;border:2px solid #dce5f1;border-radius:50%}.guide-node input:checked{border:4px solid #66a7ff;background:#fff}.guide-column[hidden],.guide-link[hidden],.guide-node[hidden]{display:none}.guide-detail{margin-top:18px;padding:20px;border-left:3px solid #66a7ff;background:#0e151f}.guide-detail h2{margin:0 0 8px;font-size:24px}.guide-detail-grid{display:grid;grid-template-columns:repeat(3,minmax(180px,1fr));gap:12px;margin-top:15px}.guide-detail-item{padding:13px;border:1px solid #29384a;border-radius:9px;background:#111923}.guide-detail-item strong{display:block;margin-bottom:6px}.guide-path{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin-top:10px}.guide-pill{padding:6px 9px;border:1px solid #31507a;border-radius:999px;background:#132641}.guide-arrow{color:var(--blue)}.guide-connectors{position:absolute;inset:0;width:100%;height:100%;z-index:1;pointer-events:none;overflow:visible}.guide-connector{fill:none;stroke:#526276;stroke-width:1.7;opacity:.78;stroke-dasharray:9 7;animation:guide-draw .55s ease-out both}.guide-connector.selected{stroke:#66a7ff;stroke-width:2.7;opacity:1}@keyframes guide-draw{from{stroke-dashoffset:80;opacity:0}to{stroke-dashoffset:0}}@media(prefers-reduced-motion:reduce){.guide-connector{animation:none}}.guide-result{margin-top:16px}.guide-result li{margin:8px 0}.catalog-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(300px,1fr);gap:16px}.catalog-form{position:sticky;top:16px}.catalog-form .cardbody>form{display:grid;gap:16px}.catalog-form label{display:grid;gap:7px;color:var(--muted);font-size:12px;font-weight:700}.catalog-form .input,.catalog-form .select{width:100%;min-width:0}.catalog-form textarea.input{min-height:84px;resize:vertical;line-height:1.45}.catalog-form label:has(input[type=checkbox]){display:flex;align-items:center;gap:9px;color:var(--text)}.catalog-form .detailactions{display:flex;gap:9px;flex-wrap:wrap;margin-top:4px}.catalog-row.off{opacity:.55}@media(max-width:1000px){.catalog-grid{grid-template-columns:1fr}.catalog-form{position:static}}`

const guideHTML = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FleetAMP Guides</title><style>`+controlPlaneCSS+guideCSS+`</style></head><body><div class="shell">`+sideNav+`<main class="main"><header class="top"><div><div class="crumb">FleetAMP / Instrumentation / Guides</div><div class="pagetitle">Instrumentation Guides</div><div class="subtitle">Choose what you want to observe. FleetAMP reveals one relevant decision at a time.</div></div><div class="topactions"><span class="badge ok">Published v{{.Version}}</span><button class="btn" type="button" data-guide-reset>Start over</button></div></header><div class="content"><section class="card"><div class="cardhead"><div><div class="cardtitle">Design an OpenTelemetry approach</div><div class="cardsub">Select a radio node to reveal the next connected branch.</div></div></div><div class="cardbody"><div class="guide-map" data-guide data-catalog="{{.EncodedCatalog}}"><div class="guide-flow"><svg class="guide-connectors" aria-hidden="true"><defs><marker id="guide-arrow-muted" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#526276"></path></marker><marker id="guide-arrow-selected" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#66a7ff"></path></marker></defs><g data-connectors></g></svg>{{range .Stages}}<div class="guide-column" data-column="{{.Key}}" {{if not .First}}hidden{{end}}><div class="guide-heading">{{.Label}}</div>{{range .Nodes}}<label class="guide-node" data-id="{{.ID}}"><input type="radio" name="{{.Stage}}" value="{{.ID}}"><span>{{.Name}}</span></label>{{end}}</div>{{if not .Last}}<div class="guide-link" data-link="{{.Next}}" hidden></div>{{end}}{{end}}</div><div class="guide-detail"><h2 data-title>Select a capability</h2><p data-summary>Only the first decision is shown. Your selection reveals the next connected branch.</p><div class="guide-path" data-path></div><div class="guide-detail-grid"><div class="guide-detail-item"><strong>Advantages</strong><span data-advantages>—</span></div><div class="guide-detail-item"><strong>Requirements</strong><span data-requirements>—</span></div><div class="guide-detail-item"><strong>Considerations</strong><span data-considerations>—</span></div></div></div></div></div></section><section class="card guide-result" data-result hidden><div class="cardhead"><div><div class="cardtitle">Recommended implementation direction</div><div class="cardsub">Guidance only—this page does not create or deploy configuration.</div></div></div><div class="cardbody"><ol data-steps></ol></div></section></div></main></div><script src="/assets/guides.js" defer></script></body></html>`

const guideAdminHTML = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guide Catalog</title><style>`+controlPlaneCSS+guideCSS+`</style></head><body><div class="shell">`+sideNav+`<main class="main"><header class="top"><div><div class="crumb">FleetAMP / Administration / Guide Catalog</div><div class="pagetitle">Guide Catalog</div><div class="subtitle">Customize the progressive instrumentation map for your organization, then publish it safely.</div></div><div class="topactions"><a class="btn" href="/instrumentation">Preview published</a><form method="post"><input type="hidden" name="action" value="publish"><button class="btn primary" type="submit">Validate &amp; publish</button></form></div></header><div class="content">{{if .Message}}<div class="notice">{{.Message}}</div>{{end}}<div class="catalog-grid"><section class="card"><div class="cardhead"><div><div class="cardtitle">Draft nodes</div><div class="cardsub">Published v{{.ActiveVersion}} remains live until this draft is validated and published.</div></div><span class="badge warn">Draft</span></div><div style="overflow:auto"><table><thead><tr><th>Stage</th><th>Name</th><th>Parents</th><th>Status</th><th>Action</th></tr></thead><tbody>{{range .Nodes}}<tr class="catalog-row {{if not .Enabled}}off{{end}}"><td>{{.Stage}}</td><td><strong>{{.Name}}</strong><div class="tiny code">{{.ID}}</div></td><td>{{join .ParentIDs}}</td><td>{{if .Enabled}}<span class="badge ok">Enabled</span>{{else}}<span class="badge off">Disabled</span>{{end}}</td><td><a class="btn" href="/settings/guide-catalog?edit={{.ID}}">Edit</a><form method="post" style="display:inline"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="{{.ID}}"><button class="btn" type="submit">Delete</button></form></td></tr>{{end}}</tbody></table></div></section><section class="card catalog-form"><div class="cardhead"><div><div class="cardtitle">{{if .Editing.ID}}Edit node{{else}}Add node{{end}}</div><div class="cardsub">Connect it using parent IDs from the preceding stage.</div></div></div><div class="cardbody"><form method="post"><input type="hidden" name="action" value="save"><label>ID<input class="input" name="id" value="{{.Editing.ID}}" pattern="[a-z0-9-]+" required></label><label>Stage<select class="select" name="stage" required>{{range .Stages}}<option value="{{.}}" {{if eq . $.Editing.Stage}}selected{{end}}>{{.}}</option>{{end}}</select></label><label>Name<input class="input" name="name" value="{{.Editing.Name}}" required></label><label>Parent IDs<input class="input" name="parents" value="{{join .Editing.ParentIDs}}" placeholder="browser, mobile"></label><label>Description<textarea class="input" name="description">{{.Editing.Description}}</textarea></label><label>Advantages<textarea class="input" name="advantages">{{.Editing.Advantages}}</textarea></label><label>Requirements<textarea class="input" name="requirements">{{.Editing.Requirements}}</textarea></label><label>Considerations<textarea class="input" name="considerations">{{.Editing.Considerations}}</textarea></label><label>Implementation steps<textarea class="input" name="steps" placeholder="One step per line">{{lines .Editing.Steps}}</textarea></label><label><input type="checkbox" name="enabled" value="true" {{if or .Editing.Enabled (not .Editing.ID)}}checked{{end}}> Enabled</label><div class="detailactions"><button class="btn primary" type="submit">Validate &amp; save draft</button><a class="btn" href="/settings/guide-catalog">Cancel</a></div></form></div></section></div><section class="card" style="margin-top:16px"><div class="cardhead"><div><div class="cardtitle">Published history</div><div class="cardsub">Rollback creates a new immutable version from the selected snapshot.</div></div></div><table><thead><tr><th>Version</th><th>Publisher</th><th>Nodes</th><th>Action</th></tr></thead><tbody>{{range .Versions}}<tr><td>v{{.Version}}</td><td>{{.CreatedBy}}</td><td>{{len .Catalog.Nodes}}</td><td>{{if ne .Version $.ActiveVersion}}<form method="post"><input type="hidden" name="action" value="rollback"><input type="hidden" name="version" value="{{.Version}}"><button class="btn" type="submit">Rollback to this version</button></form>{{else}}<span class="badge ok">Active</span>{{end}}</td></tr>{{end}}</tbody></table></section></div></main></div></body></html>`

const guideJS = `(function(){var root=document.querySelector('[data-guide]');if(!root)return;var data=JSON.parse(atob(root.dataset.catalog)),nodes={};data.nodes.forEach(function(n){nodes[n.id]=n});var stages=['capability','platform','technology','method','topology'],flow=root.querySelector('.guide-flow'),group=root.querySelector('[data-connectors]'),ns='http://www.w3.org/2000/svg';function selected(stage){var x=root.querySelector('[name="'+stage+'"]:checked');return x?x.value:''}function update(){for(var i=1;i<stages.length;i++){var stage=stages[i],parent=selected(stages[i-1]),col=root.querySelector('[data-column="'+stage+'"]'),link=root.querySelector('[data-link="'+stage+'"]');col.hidden=!parent;if(link)link.hidden=!parent;root.querySelectorAll('[name="'+stage+'"]').forEach(function(input){var label=input.closest('label'),ok=(nodes[input.value].parent_ids||[]).includes(parent);label.hidden=!ok;if(!ok)input.checked=false})}var chosen=stages.map(selected).filter(Boolean),last=nodes[chosen[chosen.length-1]];root.querySelector('[data-title]').textContent=last?last.name:'Select a capability';root.querySelector('[data-summary]').textContent=last?(last.description||'Choose the next connected option.'):'Only the first decision is shown. Your selection reveals the next connected branch.';['advantages','requirements','considerations'].forEach(function(k){root.querySelector('[data-'+k+']').textContent=last&&last[k]?last[k]:'—'});var path=root.querySelector('[data-path]');path.replaceChildren();chosen.forEach(function(id,i){if(i){var a=document.createElement('span');a.className='guide-arrow';a.textContent='→';path.append(a)}var p=document.createElement('span');p.className='guide-pill';p.textContent=nodes[id].name;path.append(p)});var result=document.querySelector('[data-result]');result.hidden=!(last&&last.steps&&last.steps.length);var ol=result.querySelector('[data-steps]');ol.replaceChildren();if(last&&last.steps)last.steps.forEach(function(s){var li=document.createElement('li');li.textContent=s;ol.append(li)});requestAnimationFrame(draw)}function draw(){group.replaceChildren();var box=flow.getBoundingClientRect();for(var i=0;i<stages.length-1;i++){var input=root.querySelector('[name="'+stages[i]+'"]:checked'),col=root.querySelector('[data-column="'+stages[i+1]+'"]');if(!input||col.hidden)continue;var a=input.closest('label').getBoundingClientRect();col.querySelectorAll('label:not([hidden])').forEach(function(label){var b=label.getBoundingClientRect(),x1=a.right-box.left,y1=a.top+a.height/2-box.top,x2=b.left-box.left,y2=b.top+b.height/2-box.top,bend=Math.max(20,(x2-x1)*.45),path=document.createElementNS(ns,'path'),on=label.querySelector('input').checked;path.setAttribute('d','M '+x1+' '+y1+' C '+(x1+bend)+' '+y1+', '+(x2-bend)+' '+y2+', '+x2+' '+y2);path.setAttribute('class','guide-connector'+(on?' selected':''));path.setAttribute('marker-end',on?'url(#guide-arrow-selected)':'url(#guide-arrow-muted)');group.append(path)})}}root.addEventListener('change',update);window.addEventListener('resize',draw);document.querySelector('[data-guide-reset]').addEventListener('click',function(){root.querySelectorAll('input').forEach(function(x){x.checked=false});update()});update()})();`

type guideStageView struct{Key,Label,Next string;Nodes []guides.Node;First,Last bool}
type guideView struct{Page string;Version int;Stages []guideStageView;EncodedCatalog string}
type guideAdminView struct{Page,Message string;Nodes []guides.Node;Editing guides.Node;Stages []string;Versions []guides.Version;ActiveVersion int}
type defaultGuideCatalogStore struct{mu sync.Mutex;draft guides.Catalog;versions []guides.Version;active int}
func newDefaultGuideCatalogStore()*defaultGuideCatalogStore{c:=guides.DefaultCatalog();now:=time.Now().UTC();v:=guides.Version{Version:1,Catalog:c,CreatedBy:"system",CreatedAt:now,PublishedAt:now};return &defaultGuideCatalogStore{draft:c,versions:[]guides.Version{v},active:1}}
func(s *defaultGuideCatalogStore)Draft(context.Context)(guides.Catalog,error){s.mu.Lock();defer s.mu.Unlock();return s.draft,nil}
func(s *defaultGuideCatalogStore)SaveDraft(_ context.Context,c guides.Catalog,_ string)error{s.mu.Lock();defer s.mu.Unlock();if e:=c.Validate();e!=nil{return e};s.draft=c;return nil}
func(s *defaultGuideCatalogStore)Active(context.Context)(guides.Version,error){s.mu.Lock();defer s.mu.Unlock();for _,v:=range s.versions{if v.Version==s.active{return v,nil}};return guides.Version{},nil}
func(s *defaultGuideCatalogStore)Publish(_ context.Context,actor string)(guides.Version,error){s.mu.Lock();defer s.mu.Unlock();if e:=s.draft.Validate();e!=nil{return guides.Version{},e};now:=time.Now().UTC();v:=guides.Version{Version:len(s.versions)+1,Catalog:s.draft,CreatedBy:actor,CreatedAt:now,PublishedAt:now};s.versions=append(s.versions,v);s.active=v.Version;return v,nil}
func(s *defaultGuideCatalogStore)Versions(context.Context)([]guides.Version,error){s.mu.Lock();defer s.mu.Unlock();out:=append([]guides.Version(nil),s.versions...);for i,j:=0,len(out)-1;i<j;i,j=i+1,j-1{out[i],out[j]=out[j],out[i]};return out,nil}
func(s *defaultGuideCatalogStore)Rollback(ctx context.Context,version int,actor string)(guides.Version,error){s.mu.Lock();for _,v:=range s.versions{if v.Version==version{s.draft=v.Catalog;s.mu.Unlock();return s.Publish(ctx,actor)}};s.mu.Unlock();return guides.Version{},strconv.ErrSyntax}
var guidePage=template.Must(template.New("guide").Parse(guideHTML))
var guideAdminPage=template.Must(template.New("guide-admin").Funcs(template.FuncMap{"join":func(v []string)string{return strings.Join(v,", ")},"lines":func(v []string)string{return strings.Join(v,"\n")}}).Parse(guideAdminHTML))

func guideStages(c guides.Catalog)[]guideStageView{labels:=map[string]string{"capability":"Capability","platform":"Platform","technology":"Technology or source","method":"Instrumentation or collection","topology":"Deployment topology"};out:=make([]guideStageView,0,len(guides.Stages));for i,s:=range guides.Stages{v:=guideStageView{Key:s,Label:labels[s],First:i==0,Last:i==len(guides.Stages)-1};if !v.Last{v.Next=guides.Stages[i+1]};for _,n:=range c.Nodes{if n.Stage==s&&n.Enabled{v.Nodes=append(v.Nodes,n)}};sort.SliceStable(v.Nodes,func(i,j int)bool{return v.Nodes[i].SortOrder<v.Nodes[j].SortOrder});out=append(out,v)};return out}
func registerGuideRoutes(mux *http.ServeMux,dependencies ...any){
	store:=storage.GuideCatalogStore(newDefaultGuideCatalogStore());auth:=&authManager{}
	if len(dependencies)>0{if configured,ok:=dependencies[0].(storage.GuideCatalogStore);ok&&configured!=nil{store=configured}}
	if len(dependencies)>1{if configured,ok:=dependencies[1].(*authManager);ok&&configured!=nil{auth=configured}}
	mux.HandleFunc("GET /assets/guides.js",func(w http.ResponseWriter,_ *http.Request){w.Header().Set("Content-Type","text/javascript; charset=utf-8");w.Header().Set("Cache-Control","no-store");_,_=w.Write([]byte(guideJS))})
	mux.HandleFunc("GET /instrumentation",func(w http.ResponseWriter,r *http.Request){v,e:=store.Active(r.Context());if e!=nil{internalServerError(w,e);return};raw,_:=json.Marshal(v.Catalog);w.Header().Set("Content-Type","text/html; charset=utf-8");_ = guidePage.Execute(w,guideView{Page:"instrumentation",Version:v.Version,Stages:guideStages(v.Catalog),EncodedCatalog:base64.StdEncoding.EncodeToString(raw)})})
	mux.HandleFunc("/settings/guide-catalog",func(w http.ResponseWriter,r *http.Request){if currentRole(auth,r)!=roleAdmin{http.Error(w,"administrator access required",http.StatusForbidden);return};actor:=currentUsername(auth,r);message:="";if r.Method==http.MethodPost{if e:=r.ParseForm();e!=nil{http.Error(w,"invalid form",400);return};action:=r.FormValue("action");switch action{case "save","delete":c,e:=store.Draft(r.Context());if e!=nil{internalServerError(w,e);return};id:=strings.TrimSpace(r.FormValue("id"));found:=-1;for i:=range c.Nodes{if c.Nodes[i].ID==id{found=i;break}};if action=="delete"{if found<0{http.Error(w,"node not found",404);return};c.Nodes=append(c.Nodes[:found],c.Nodes[found+1:]...)}else{n:=guides.Node{ID:id,Stage:strings.TrimSpace(r.FormValue("stage")),Name:strings.TrimSpace(r.FormValue("name")),Description:strings.TrimSpace(r.FormValue("description")),Advantages:strings.TrimSpace(r.FormValue("advantages")),Requirements:strings.TrimSpace(r.FormValue("requirements")),Considerations:strings.TrimSpace(r.FormValue("considerations")),ParentIDs:splitValues(r.FormValue("parents")),Steps:splitLines(r.FormValue("steps")),Enabled:r.FormValue("enabled")=="true",SortOrder:len(c.Nodes)};if found>=0{n.SortOrder=c.Nodes[found].SortOrder;c.Nodes[found]=n}else{c.Nodes=append(c.Nodes,n)}};if e=store.SaveDraft(r.Context(),c,actor);e!=nil{http.Error(w,e.Error(),422);return};message="Draft validated and saved";case "publish":v,e:=store.Publish(r.Context(),actor);if e!=nil{http.Error(w,e.Error(),422);return};message="Guide version "+strconv.Itoa(v.Version)+" published";case "rollback":version,e:=strconv.Atoi(r.FormValue("version"));if e!=nil{http.Error(w,"invalid version",400);return};v,e:=store.Rollback(r.Context(),version,actor);if e!=nil{http.Error(w,e.Error(),422);return};message="Rolled back as new version "+strconv.Itoa(v.Version);default:http.Error(w,"unsupported action",400);return};http.Redirect(w,r,"/settings/guide-catalog?message="+url.QueryEscape(message),http.StatusSeeOther);return};if r.Method!=http.MethodGet{http.Error(w,"method not allowed",405);return};c,e:=store.Draft(r.Context());if e!=nil{internalServerError(w,e);return};active,e:=store.Active(r.Context());if e!=nil{internalServerError(w,e);return};versions,e:=store.Versions(r.Context());if e!=nil{internalServerError(w,e);return};editing:=guides.Node{};id:=r.URL.Query().Get("edit");for _,n:=range c.Nodes{if n.ID==id{editing=n}};w.Header().Set("Content-Type","text/html; charset=utf-8");_ = guideAdminPage.Execute(w,guideAdminView{Page:"settings-guide-catalog",Message:r.URL.Query().Get("message"),Nodes:c.Nodes,Editing:editing,Stages:guides.Stages,Versions:versions,ActiveVersion:active.Version})})
}
func splitValues(v string)[]string{var out []string;for _,x:=range strings.FieldsFunc(v,func(r rune)bool{return r==','||r==' '||r=='\n'}){if x=strings.TrimSpace(x);x!=""{out=append(out,x)}};return out}
func splitLines(v string)[]string{var out []string;for _,x:=range strings.Split(v,"\n"){if x=strings.TrimSpace(x);x!=""{out=append(out,x)}};return out}
